package com.shikshasetu.controller;
import com.shikshasetu.ai.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import java.util.NoSuchElementException;
@RestController @RequestMapping("/api/ai") public class AiModelController {private final AiModelTrainingService training;private final AiPredictionService prediction;public AiModelController(AiModelTrainingService t,AiPredictionService p){training=t;prediction=p;}@GetMapping("/model/status")public AiModelStatus status(){return training.status();}@PostMapping(value="/model/train",consumes="multipart/form-data")public AiTrainingResult train(@RequestPart("file")MultipartFile file){try{return training.train(file);}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage(),e);}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,e.getMessage(),e);}}@GetMapping("/students/{studentId}/history")public java.util.List<com.shikshasetu.model.AiAssessment> history(@PathVariable Long studentId){return prediction.history(studentId);}@PostMapping("/students/{studentId}/assessment")public AiAssessmentResponse assess(@PathVariable Long studentId){try{return prediction.assess(studentId);}catch(NoSuchElementException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,e.getMessage(),e);}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage(),e);}}}
